syntax:
int *p = new int;        // box with unknown (garbage) value
*p = 42;                 // use it through the pointer

int *q = new int(5);     // box that starts as 5
double *d = new double(3.75);
int *z = new int();      // box that starts as 0

delete p;                // give the box back
p = nullptr;             // p now points to nothing

// new returns an ADDRESS, so the left side must be a pointer:
// int x = new int(5);   // wrong: int cannot hold an address

sample.code:
#include <iostream>
using namespace std;

int main() {
    int *p = new int(5);
    cout << "Value: " << *p << endl;
    *p = *p + 10;
    cout << "Now: " << *p << endl;
    delete p;
    p = nullptr;
    if (p == nullptr) {
        cout << "p points to nothing" << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int *a = new int;
    *a = 7;
    int *b = new int(20);
    int *c = new int();
    double *d = new double(3.75);

    cout << "a = " << *a << endl;
    cout << "b = " << *b << endl;
    cout << "c = " << *c << endl;
    cout << "d = " << *d << endl;

    delete a;
    delete b;
    delete c;
    delete d;
    return 0;
}

#include <iostream>
using namespace std;

int *makeBox(int start) {
    int *box = new int(start);
    return box;
}

int main() {
    int *x = makeBox(10);
    int *y = makeBox(20);
    *x = *x + *y;
    cout << "x = " << *x << ", y = " << *y << endl;
    delete x;
    delete y;
    x = nullptr;
    y = nullptr;
    return 0;
}

